    ctx2 = await page.context.browser.new_context(
        base_url=server.base_url, viewport={"width": 1280, "height": 900})
    org_page = await ctx2.new_page()
    await ui_login(org_page, "org", server.org_email, server.org_password)
    await org_page.goto("/org/shifts", wait_until="domcontentloaded")
    await org_page.select_option("#statusFilter", "open_requested")
    await org_page.click("button.btn-outline-secondary")  # loadShifts
    decide_btn = org_page.locator('[onclick*="openDecisionModal"]').first
    await expect(decide_btn).to_be_visible()
    await decide_btn.click()
    await org_page.select_option("#decisionChoice", "approve")
    await org_page.fill("#decisionReason", "Acceptance shift approved")
    async with org_page.expect_response(
        lambda r: "/decision" in r.url and r.request.method == "POST"
    ) as dec_info:
        await org_page.click('button:has-text("Submit Decision")')
