    logs = server.db_fetchall(
        "SELECT action, from_stage_code, to_stage_code, reason "
        "FROM token_stage_logs WHERE token_id = :t ORDER BY id", {"t": token_id})
    actions = [l[0] for l in logs]

    assert logs[0][0] == "start" and logs[0][2] == "registration"
    assert "advance" in actions and "recall" in actions
    assert not any(l[0] == "skip" for l in logs), logs  # skip was refused
    recall_rows = [l for l in logs if l[0] == "recall"]
    assert recall_rows and recall_rows[0][2] == "registration"
    assert recall_rows[0][3] == REASON, recall_rows
    state = server.db_fetchone(
        "SELECT current_stage_id, status FROM token_workflow_states "
        "WHERE token_id = :t", {"t": token_id})
    cur = server.db_fetchone(
        "SELECT code FROM workflow_stages WHERE id = :s", {"s": state[0]})
    assert cur[0] == "verification"
